import {
  Client,
  CustomersApi,
  Environment,
  InvoicesApi,
  ProductFamiliesApi,
  ProductsApi,
  SubscriptionsApi,
} from 'maxio-advanced-billinglib';

function resolveEnvironment(value: string | undefined): Environment {
  switch ((value ?? 'US').toUpperCase()) {
    case 'EU':
      return Environment.Eu;
    case 'MAXIO API GATEWAY':
    case 'GATEWAY':
      return Environment.MaxioApiGateway;
    default:
      return Environment.Us;
  }
}

export function isMaxioConfigured(): boolean {
  return Boolean(process.env.MAXIO_API_KEY && process.env.MAXIO_SITE);
}

export function createMaxioClient(): Client {
  const apiKey = process.env.MAXIO_API_KEY;
  const site = process.env.MAXIO_SITE;
  if (!apiKey || !site) {
    throw new Error('MAXIO_API_KEY and MAXIO_SITE are required');
  }

  return new Client({
    environment: resolveEnvironment(process.env.MAXIO_ENVIRONMENT),
    site,
    basicAuthCredentials: {
      username: apiKey,
      password: process.env.MAXIO_PASSWORD ?? 'X',
    },
    httpClientOptions: {
      timeout: 30000,
      retryConfig: { maxNumberOfRetries: 2, backoffFactor: 2 },
    },
  });
}

export function maxioApis(client: Client) {
  return {
    customers: new CustomersApi(client),
    productFamilies: new ProductFamiliesApi(client),
    products: new ProductsApi(client),
    subscriptions: new SubscriptionsApi(client),
    invoices: new InvoicesApi(client),
  };
}

import { Client, Environment, OrdersApi } from 'paypallib';

function resolveEnvironment(value: string | undefined): Environment {
  return (value ?? 'Sandbox').toLowerCase() === 'production'
    ? Environment.Production
    : Environment.Sandbox;
}

export function isPayPalConfigured(): boolean {
  return Boolean(
    process.env.PAYPAL_CLIENT_ID && process.env.PAYPAL_CLIENT_SECRET
  );
}

export function createPayPalClient(): Client {
  const oauthClientId = process.env.PAYPAL_CLIENT_ID;
  const oauthClientSecret = process.env.PAYPAL_CLIENT_SECRET;
  if (!oauthClientId || !oauthClientSecret) {
    throw new Error('PAYPAL_CLIENT_ID and PAYPAL_CLIENT_SECRET are required');
  }

  return new Client({
    environment: resolveEnvironment(process.env.PAYPAL_ENVIRONMENT),
    clientCredentialsAuthCredentials: {
      oauthClientId,
      oauthClientSecret,
    },
    httpClientOptions: {
      timeout: 30000,
      retryConfig: { maxNumberOfRetries: 2, backoffFactor: 2 },
    },
  });
}

export function paypalApis(client: Client) {
  return {
    orders: new OrdersApi(client),
  };
}

export interface CheckoutSession {
  id: string;
  demo: boolean;
  customerId?: number;
  productId?: number;
  productFamilyId?: string | number;
  subscriptionId?: number;
  invoiceUid?: string;
  invoiceNumber?: string;
  amount: string;
  currency: string;
  planName: string;
  paypalOrderId?: string;
  customerEmail: string;
  customerName: string;
  createdAt: string;
}

const sessions = new Map<string, CheckoutSession>();

export function saveSession(session: CheckoutSession): void {
  sessions.set(session.id, session);
}

export function getSession(id: string): CheckoutSession | undefined {
  return sessions.get(id);
}

export function updateSession(
  id: string,
  patch: Partial<CheckoutSession>
): CheckoutSession {
  const existing = sessions.get(id);
  if (!existing) {
    throw new Error(`Unknown checkout session: ${id}`);
  }
  const next = { ...existing, ...patch };
  sessions.set(id, next);
  return next;
}

import { randomUUID } from 'node:crypto';
import {
  ApiError,
  CollectionMethod,
  IntervalUnit,
  InvoicePaymentMethodType,
  type CreateCustomerRequest,
  type CreateInvoicePaymentRequest,
  type CreateInvoiceRequest,
  type CreateOrUpdateProductRequest,
  type CreateProductFamilyRequest,
  type CreateSubscriptionRequest,
  type Invoice,
} from 'maxio-advanced-billinglib';
import {
  ApiError as PayPalApiError,
  ApplicationContextShippingPreference,
  CheckoutPaymentIntent,
  type OrderRequest,
} from 'paypallib';
import {
  createMaxioClient,
  isMaxioConfigured,
  maxioApis,
} from '../lib/maxioClient.js';
import {
  createPayPalClient,
  isPayPalConfigured,
  paypalApis,
} from '../lib/paypalClient.js';
import {
  getSession,
  saveSession,
  updateSession,
  type CheckoutSession,
} from '../lib/sessionStore.js';

export interface StartCheckoutInput {
  firstName: string;
  lastName: string;
  email: string;
  organization?: string;
  planName?: string;
  priceCents?: number;
}

export interface StartCheckoutResult {
  sessionId: string;
  demo: boolean;
  approveUrl: string;
  summary: {
    customerId?: number;
    productId?: number;
    subscriptionId?: number;
    invoiceUid?: string;
    invoiceNumber?: string;
    amount: string;
    planName: string;
    paypalOrderId?: string;
  };
}

export interface CompleteCheckoutResult {
  demo: boolean;
  paidStatus: string;
  invoiceStatus?: string;
  invoiceDueAmount?: string;
  nextBillingDate?: string | null;
  subscriptionState?: string;
  paypalOrderStatus?: string;
  paypalCaptureId?: string;
  summary: CheckoutSession;
}

function appBaseUrl(): string {
  return (process.env.APP_BASE_URL ?? 'http://localhost:3000').replace(
    /\/$/,
    ''
  );
}

function moneyFromCents(cents: number): string {
  return (cents / 100).toFixed(2);
}

function formatApiError(err: unknown): string {
  if (err instanceof ApiError || err instanceof PayPalApiError) {
    return `HTTP ${err.statusCode}: ${JSON.stringify(err.body)}`;
  }
  if (err instanceof Error) return err.message;
  return String(err);
}

async function createPlanAndCustomer(input: StartCheckoutInput) {
  const client = createMaxioClient();
  const apis = maxioApis(client);
  const stamp = Date.now();
  const planName = input.planName?.trim() || 'Starter Plan';
  const priceCents = input.priceCents ?? 2900;
  const handle = `starter-${stamp}`;

  let productFamilyId =
    process.env.MAXIO_PRODUCT_FAMILY_ID?.trim() || undefined;

  if (!productFamilyId) {
    const familyBody: CreateProductFamilyRequest = {
      productFamily: {
        name: `Hackathon Catalog ${stamp}`,
        description: 'Demo catalog for Maxio + PayPal checkout',
      },
    };
    const familyRes = await apis.productFamilies.createProductFamily(familyBody);
    productFamilyId = String(familyRes.result.productFamily?.id);
  }

  const productBody: CreateOrUpdateProductRequest = {
    product: {
      name: planName,
      description: `${planName} billed monthly via PayPal remittance`,
      handle,
      priceInCents: BigInt(priceCents),
      interval: 1,
      intervalUnit: IntervalUnit.Month,
      requireCreditCard: false,
      autoCreateSignupPage: false,
    },
  };
  const productRes = await apis.products.createProduct(
    productFamilyId,
    productBody
  );
  const productId = productRes.result.product?.id;
  if (!productId) throw new Error('Maxio did not return a product id');

  const customerBody: CreateCustomerRequest = {
    customer: {
      firstName: input.firstName,
      lastName: input.lastName,
      email: input.email,
      organization: input.organization,
      reference: `hackathon-${stamp}`,
    },
  };
  const customerRes = await apis.customers.createCustomer(customerBody);
  const customerId = customerRes.result.customer?.id;
  if (!customerId) throw new Error('Maxio did not return a customer id');

  const subscriptionBody: CreateSubscriptionRequest = {
    subscription: {
      productId,
      customerId,
      paymentCollectionMethod: CollectionMethod.Remittance,
      reference: `sub-${stamp}`,
    },
  };
  const subRes = await apis.subscriptions.createSubscription(subscriptionBody);
  const subscription = subRes.result.subscription;
  const subscriptionId = subscription?.id;
  if (!subscriptionId) throw new Error('Maxio did not return a subscription id');

  let invoice: Invoice | undefined;
  const listed = await apis.invoices.listInvoices({
    subscriptionId,
    perPage: 10,
  });
  invoice = listed.result?.[0];

  if (!invoice?.uid) {
    const invoiceBody: CreateInvoiceRequest = {
      invoice: {
        lineItems: [
          {
            title: planName,
            quantity: 1,
            unitPrice: moneyFromCents(priceCents),
          },
        ],
      },
    };
    const created = await apis.invoices.createInvoice(
      subscriptionId,
      invoiceBody
    );
    invoice = created.result.invoice;
  }

  if (!invoice?.uid) throw new Error('Maxio did not return an invoice uid');

  const amount =
    invoice.dueAmount ||
    invoice.totalAmount ||
    moneyFromCents(priceCents);

  return {
    productFamilyId,
    productId,
    customerId,
    subscriptionId,
    invoice,
    amount,
    planName,
    nextBillingDate: subscription.nextAssessmentAt ?? null,
  };
}

async function createPayPalOrder(args: {
  amount: string;
  currency: string;
  invoiceUid: string;
  invoiceNumber?: string;
  description: string;
  sessionId: string;
}) {
  const client = createPayPalClient();
  const { orders } = paypalApis(client);

  const body: OrderRequest = {
    intent: CheckoutPaymentIntent.Capture,
    purchaseUnits: [
      {
        referenceId: args.invoiceUid,
        description: args.description,
        customId: args.sessionId,
        invoiceId: args.invoiceNumber ?? args.invoiceUid.slice(0, 127),
        amount: {
          currencyCode: args.currency,
          value: args.amount,
        },
      },
    ],
    applicationContext: {
      brandName: 'Maxio PayPal Billing',
      shippingPreference: ApplicationContextShippingPreference.NoShipping,
      returnUrl: `${appBaseUrl()}/return?sessionId=${args.sessionId}`,
      cancelUrl: `${appBaseUrl()}/?canceled=1&sessionId=${args.sessionId}`,
      userAction: 'PAY_NOW' as never,
    },
  };

  // Prefer enum if present; fall back to string for userAction
  try {
    const { ApplicationContextUserAction } = await import('paypallib');
    if (ApplicationContextUserAction?.PayNow) {
      body.applicationContext!.userAction = ApplicationContextUserAction.PayNow;
    }
  } catch {
    // keep PAY_NOW string if enum import shape differs
  }

  const response = await orders.createOrder(
    body,
    undefined,
    undefined,
    undefined,
    undefined,
    'return=representation'
  );

  const order = response.result;
  const approveUrl = order.links?.find((l) => l.rel === 'approve')?.href;
  if (!order.id || !approveUrl) {
    throw new Error('PayPal order missing id or approve link');
  }

  return { orderId: order.id, approveUrl, status: order.status };
}

export async function startCheckout(
  input: StartCheckoutInput
): Promise<StartCheckoutResult> {
  const sessionId = randomUUID();
  const planName = input.planName?.trim() || 'Starter Plan';
  const priceCents = input.priceCents ?? 2900;
  const amount = moneyFromCents(priceCents);
  const currency = 'USD';
  const demo = !(isMaxioConfigured() && isPayPalConfigured());

  if (demo) {
    const fakeInvoiceUid = `inv_demo_${sessionId.slice(0, 8)}`;
    saveSession({
      id: sessionId,
      demo: true,
      customerId: 1001,
      productId: 2002,
      subscriptionId: 3003,
      invoiceUid: fakeInvoiceUid,
      invoiceNumber: 'DEMO-1001',
      amount,
      currency,
      planName,
      paypalOrderId: `DEMO-ORDER-${sessionId.slice(0, 8)}`,
      customerEmail: input.email,
      customerName: `${input.firstName} ${input.lastName}`,
      createdAt: new Date().toISOString(),
    });

    return {
      sessionId,
      demo: true,
      approveUrl: `${appBaseUrl()}/return?sessionId=${sessionId}&token=DEMO`,
      summary: {
        customerId: 1001,
        productId: 2002,
        subscriptionId: 3003,
        invoiceUid: fakeInvoiceUid,
        invoiceNumber: 'DEMO-1001',
        amount,
        planName,
        paypalOrderId: `DEMO-ORDER-${sessionId.slice(0, 8)}`,
      },
    };
  }

  try {
    const created = await createPlanAndCustomer(input);
    saveSession({
      id: sessionId,
      demo: false,
      customerId: created.customerId,
      productId: created.productId,
      productFamilyId: created.productFamilyId,
      subscriptionId: created.subscriptionId,
      invoiceUid: created.invoice.uid,
      invoiceNumber: created.invoice.number,
      amount: created.amount,
      currency,
      planName: created.planName,
      customerEmail: input.email,
      customerName: `${input.firstName} ${input.lastName}`,
      createdAt: new Date().toISOString(),
    });

    const paypal = await createPayPalOrder({
      amount: created.amount,
      currency,
      invoiceUid: created.invoice.uid!,
      invoiceNumber: created.invoice.number,
      description: created.planName,
      sessionId,
    });

    updateSession(sessionId, { paypalOrderId: paypal.orderId });

    return {
      sessionId,
      demo: false,
      approveUrl: paypal.approveUrl,
      summary: {
        customerId: created.customerId,
        productId: created.productId,
        subscriptionId: created.subscriptionId,
        invoiceUid: created.invoice.uid,
        invoiceNumber: created.invoice.number,
        amount: created.amount,
        planName: created.planName,
        paypalOrderId: paypal.orderId,
      },
    };
  } catch (err) {
    throw new Error(`Checkout start failed: ${formatApiError(err)}`);
  }
}

export async function completeCheckout(
  sessionId: string,
  paypalToken?: string
): Promise<CompleteCheckoutResult> {
  const session = getSession(sessionId);
  if (!session) {
    throw new Error('Checkout session not found. Start a new checkout.');
  }

  if (session.demo) {
    const nextBilling = new Date();
    nextBilling.setMonth(nextBilling.getMonth() + 1);
    return {
      demo: true,
      paidStatus: 'paid',
      invoiceStatus: 'paid',
      invoiceDueAmount: '0.00',
      nextBillingDate: nextBilling.toISOString(),
      subscriptionState: 'active',
      paypalOrderStatus: 'COMPLETED',
      paypalCaptureId: `CAP-DEMO-${sessionId.slice(0, 8)}`,
      summary: session,
    };
  }

  const orderId = paypalToken || session.paypalOrderId;
  if (!orderId) throw new Error('Missing PayPal order id');
  if (!session.invoiceUid || !session.subscriptionId) {
    throw new Error('Session is missing Maxio invoice/subscription ids');
  }

  try {
    const paypalClient = createPayPalClient();
    const { orders } = paypalApis(paypalClient);
    const captured = await orders.captureOrder(
      orderId,
      undefined,
      undefined,
      'return=representation'
    );
    const order = captured.result;
    const captureId =
      order.purchaseUnits?.[0]?.payments?.captures?.[0]?.id ?? order.id;

    const maxioClient = createMaxioClient();
    const apis = maxioApis(maxioClient);

    const paymentBody: CreateInvoicePaymentRequest = {
      payment: {
        amount: session.amount,
        memo: `PayPal capture ${captureId}`,
        method: InvoicePaymentMethodType.Other,
        details: `paypal_order=${orderId};capture=${captureId}`,
      },
    };
    const paidInvoice = await apis.invoices.recordPaymentForInvoice(
      session.invoiceUid,
      paymentBody
    );

    const subRes = await apis.subscriptions.readSubscription(
      session.subscriptionId
    );
    const subscription = subRes.result.subscription;

    updateSession(sessionId, { paypalOrderId: orderId });

    return {
      demo: false,
      paidStatus:
        paidInvoice.result.status === 'paid' ||
        Number(paidInvoice.result.dueAmount ?? '1') === 0
          ? 'paid'
          : String(paidInvoice.result.status ?? 'unknown'),
      invoiceStatus: paidInvoice.result.status,
      invoiceDueAmount: paidInvoice.result.dueAmount,
      nextBillingDate: subscription?.nextAssessmentAt ?? null,
      subscriptionState: subscription?.state,
      paypalOrderStatus: order.status,
      paypalCaptureId: captureId,
      summary: getSession(sessionId)!,
    };
  } catch (err) {
    throw new Error(`Checkout completion failed: ${formatApiError(err)}`);
  }
}

export function getConfigStatus() {
  return {
    maxioConfigured: isMaxioConfigured(),
    paypalConfigured: isPayPalConfigured(),
    demoMode: !(isMaxioConfigured() && isPayPalConfigured()),
  };
}

