const form = document.getElementById('checkoutForm');
const startBtn = document.getElementById('startBtn');
const logEl = document.getElementById('log');
const modeBadge = document.getElementById('modeBadge');

async function refreshMode() {
  try {
    const res = await fetch('/api/health');
    const data = await res.json();
    if (data.demoMode) {
      modeBadge.textContent = 'Demo mode — add Maxio + PayPal credentials in .env for live calls';
      modeBadge.className = 'badge demo';
    } else {
      modeBadge.textContent = 'Live mode — Maxio and PayPal credentials detected';
      modeBadge.className = 'badge live';
    }
  } catch {
    modeBadge.textContent = 'Could not reach API';
    modeBadge.className = 'badge';
  }
}

form.addEventListener('submit', async (event) => {
  event.preventDefault();
  startBtn.disabled = true;
  startBtn.textContent = 'Creating Maxio customer, plan & invoice…';
  logEl.hidden = true;

  const fd = new FormData(form);
  const payload = Object.fromEntries(fd.entries());
  payload.priceCents = Number(payload.priceCents);

  try {
    const res = await fetch('/api/checkout/start', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(payload),
    });
    const data = await res.json();
    if (!res.ok) throw new Error(data.error || 'Checkout start failed');

    logEl.hidden = false;
    logEl.textContent = JSON.stringify(data.summary, null, 2);
    startBtn.textContent = 'Redirecting to PayPal…';
    window.location.href = data.approveUrl;
  } catch (err) {
    logEl.hidden = false;
    logEl.textContent = err instanceof Error ? err.message : String(err);
    startBtn.disabled = false;
    startBtn.textContent = 'Create invoice & pay with PayPal';
  }
});

refreshMode();

if (new URLSearchParams(location.search).get('canceled')) {
  logEl.hidden = false;
  logEl.textContent = 'PayPal checkout was canceled. Start again when ready.';
}

const resultEl = document.getElementById('result');
const params = new URLSearchParams(location.search);
const sessionId = params.get('sessionId');
const token = params.get('token');

function formatDate(value) {
  if (!value) return '—';
  const d = new Date(value);
  return Number.isNaN(d.getTime()) ? value : d.toLocaleString();
}

async function run() {
  if (!sessionId) {
    resultEl.innerHTML = '<p class="error">Missing sessionId.</p>';
    return;
  }

  try {
    const qs = new URLSearchParams({ sessionId });
    if (token) qs.set('token', token);
    const res = await fetch(`/api/checkout/complete?${qs}`);
    const data = await res.json();
    if (!res.ok) throw new Error(data.error || 'Completion failed');

    resultEl.innerHTML = `
      <h2>${data.paidStatus === 'paid' ? 'Invoice paid' : 'Checkout finished'}</h2>
      <dl>
        <dt>Paid status</dt><dd>${data.paidStatus}</dd>
        <dt>Invoice status</dt><dd>${data.invoiceStatus ?? '—'}</dd>
        <dt>Amount due</dt><dd>${data.invoiceDueAmount ?? '0.00'}</dd>
        <dt>Next billing date</dt><dd>${formatDate(data.nextBillingDate)}</dd>
        <dt>Subscription</dt><dd>${data.subscriptionState ?? '—'}</dd>
        <dt>PayPal status</dt><dd>${data.paypalOrderStatus ?? '—'}</dd>
        <dt>Capture id</dt><dd>${data.paypalCaptureId ?? '—'}</dd>
        <dt>Mode</dt><dd>${data.demo ? 'Demo' : 'Live'}</dd>
      </dl>
    `;
  } catch (err) {
    resultEl.innerHTML = `<p class="error">${
      err instanceof Error ? err.message : String(err)
    }</p>`;
  }
}

run();

