/**
 * Maxio sites on legacy Statements return `[{ invoice: {...} }]`, while
 * Relationship Invoicing returns `{ invoices: [...] }`. The generated SDK only
 * accepts the latter, so we fetch + normalize ourselves.
 */
async function fetchOpenInvoice(
  subscriptionId: number,
  fallbackAmount: string
): Promise<OpenInvoiceSummary> {
  const site = process.env.MAXIO_SITE;
  const apiKey = process.env.MAXIO_API_KEY;
  if (!site || !apiKey) {
    throw new Error('MAXIO_API_KEY and MAXIO_SITE are required');
  }

  const password = process.env.MAXIO_PASSWORD ?? 'X';
  const auth = Buffer.from(`${apiKey}:${password}`).toString('base64');
  const url = new URL(`https://${site}.chargify.com/invoices.json`);
  url.searchParams.set('subscription_id', String(subscriptionId));
  url.searchParams.set('per_page', '10');

  const res = await fetch(url, {
    headers: {
      Accept: 'application/json',
      Authorization: `Basic ${auth}`,
    },
  });
  if (!res.ok) {
    throw new Error(`Maxio invoice list failed: HTTP ${res.status}`);
  }

  const body = (await res.json()) as unknown;

  // Relationship Invoicing: { invoices: [ { uid, number, due_amount, status } ] }
  if (
    body &&
    typeof body === 'object' &&
    Array.isArray((body as { invoices?: unknown }).invoices)
  ) {
    const invoices = (body as { invoices: Record<string, unknown>[] }).invoices;
    const open =
      invoices.find((inv) => {
        const status = String(inv.status ?? '');
        return status === 'open' || status === 'pending' || Number(inv.due_amount) > 0;
      }) ?? invoices[0];
    if (open?.uid) {
      return {
        reference: String(open.uid),
        number: open.number != null ? String(open.number) : undefined,
        amount: String(open.due_amount ?? open.total_amount ?? fallbackAmount),
        format: 'relationship',
      };
    }
  }

  // Legacy Statements: [ { invoice: { id, number, amount_due_in_cents, state } } ]
  if (Array.isArray(body)) {
    const wrapped = body
      .map((row) =>
        row && typeof row === 'object'
          ? (row as { invoice?: Record<string, unknown> }).invoice
          : undefined
      )
      .filter(Boolean) as Record<string, unknown>[];
    const unpaid =
      wrapped.find((inv) => {
        const state = String(inv.state ?? '');
        return (
          state === 'unpaid' ||
          state === 'pending' ||
          Number(inv.amount_due_in_cents ?? 0) > 0
        );
      }) ?? wrapped[0];
    if (unpaid?.id != null) {
      const dueCents = Number(unpaid.amount_due_in_cents ?? unpaid.total_amount_in_cents ?? 0);
      return {
        reference: String(unpaid.id),
        number: unpaid.number != null ? String(unpaid.number) : undefined,
        amount: dueCents > 0 ? moneyFromCents(dueCents) : fallbackAmount,
        format: 'legacy',
      };
    }
  }

  return {
    reference: `sub-${subscriptionId}`,
    amount: fallbackAmount,
    format: 'legacy',
  };
}

async function createPlanAndCustomer(input: StartCheckoutInput) {
  const client = createMaxioClient();
  const apis = maxioApis(client);
  const stamp = Date.now();
  const planName = input.planName?.trim() || 'Starter Plan';
  const priceCents = input.priceCents ?? 2900;
  const handle = `starter-${stamp}`;

  let productFamilyId =
    process.env.MAXIO_PRODUCT_FAMILY_ID?.trim() || undefined;

  if (!productFamilyId) {
    const familyBody: CreateProductFamilyRequest = {
      productFamily: {
        name: `Hackathon Catalog ${stamp}`,
        description: 'Demo catalog for Maxio + PayPal checkout',
      },
    };
    const familyRes = await apis.productFamilies.createProductFamily(familyBody);
    productFamilyId = String(familyRes.result.productFamily?.id);
  }

  const productBody: CreateOrUpdateProductRequest = {
    product: {
      name: planName,
      description: `${planName} billed monthly via PayPal remittance`,
      handle,
      priceInCents: BigInt(priceCents),
      interval: 1,
      intervalUnit: IntervalUnit.Month,
      requireCreditCard: false,
      autoCreateSignupPage: false,
    },
  };
  const productRes = await apis.products.createProduct(
    productFamilyId,
    productBody
  );
  const productId = productRes.result.product?.id;
  if (!productId) throw new Error('Maxio did not return a product id');

  const customerBody: CreateCustomerRequest = {
    customer: {
      firstName: input.firstName,
      lastName: input.lastName,
      email: input.email,
      organization: input.organization,
      reference: `hackathon-${stamp}`,
    },
  };
  const customerRes = await apis.customers.createCustomer(customerBody);
  const customerId = customerRes.result.customer?.id;
  if (!customerId) throw new Error('Maxio did not return a customer id');

  const subscriptionBody: CreateSubscriptionRequest = {
    subscription: {
      productId,
      customerId,
      paymentCollectionMethod: CollectionMethod.Remittance,
      reference: `sub-${stamp}`,
    },
  };
  const subRes = await apis.subscriptions.createSubscription(subscriptionBody);
  const subscription = subRes.result.subscription;
  const subscriptionId = subscription?.id;
  if (!subscriptionId) throw new Error('Maxio did not return a subscription id');

  const balanceCents = Number(
    subscription.balanceInCents ??
      subscription.currentBillingAmountInCents ??
      priceCents
  );
  const fallbackAmount = moneyFromCents(balanceCents > 0 ? balanceCents : priceCents);
  const invoice = await fetchOpenInvoice(subscriptionId, fallbackAmount);

  return {
    productFamilyId,
    productId,
    customerId,
    subscriptionId,
    invoice,
    amount: invoice.amount,
    planName,
    nextBillingDate: subscription.nextAssessmentAt ?? null,
  };
}

