async function createPayPalOrder(args: {
  amount: string;
  currency: string;
  invoiceReference: string;
  invoiceNumber?: string;
  description: string;
  sessionId: string;
}) {
  const client = createPayPalClient();
  const { orders } = paypalApis(client);

  const body: OrderRequest = {
    intent: CheckoutPaymentIntent.Capture,
    purchaseUnits: [
      {
        referenceId: args.invoiceReference.slice(0, 256),
        description: args.description,
        customId: args.sessionId,
        invoiceId: (args.invoiceNumber ?? args.invoiceReference).slice(0, 127),
        amount: {
          currencyCode: args.currency,
          value: args.amount,
        },
      },
    ],
    applicationContext: {
      brandName: 'Maxio PayPal Billing',
      shippingPreference: ApplicationContextShippingPreference.NoShipping,
      returnUrl: `${appBaseUrl()}/return?sessionId=${args.sessionId}`,
      cancelUrl: `${appBaseUrl()}/?canceled=1&sessionId=${args.sessionId}`,
    },
  };

  const response = await orders.createOrder(
    body,
    undefined,
    undefined,
    undefined,
    undefined,
    'return=representation'
  );

  const order = response.result;
  const approveUrl = order.links?.find((l) => l.rel === 'approve')?.href;
  if (!order.id || !approveUrl) {
    throw new Error('PayPal order missing id or approve link');
  }

  return { orderId: order.id, approveUrl, status: order.status };
}

