import { randomUUID } from 'node:crypto';
import {
  ApiError,
  CollectionMethod,
  CustomerErrorResponseError,
  CustomerErrorResponseErrors,
  IntervalUnit,
  InvoicePaymentMethodType,
  type CreateCustomerRequest,
  type CreateOrUpdateProductRequest,
  type CreateProductFamilyRequest,
  type CreateSubscriptionRequest,
  type RecordPaymentRequest,
} from 'maxio-advanced-billinglib';
import {
  ApiError as PayPalApiError,
  ApplicationContextShippingPreference,
  CheckoutPaymentIntent,
  type OrderRequest,
} from 'paypallib';
import {
  createMaxioClient,
  isMaxioConfigured,
  maxioApis,
} from '../lib/maxioClient.js';
import {
  createPayPalClient,
  isPayPalConfigured,
  paypalApis,
} from '../lib/paypalClient.js';
import {
  getSession,
  saveSession,
  updateSession,
  type CheckoutSession,
} from '../lib/sessionStore.js';

/** App-level error carrying a real Maxio typed API failure. */
export class MaxioTypedApiError extends Error {
  readonly statusCode: number;
  readonly errorType: 'CustomerErrorResponseError';
  readonly errors: unknown;

  constructor(args: {
    message: string;
    statusCode: number;
    errorType: 'CustomerErrorResponseError';
    errors: unknown;
  }) {
    super(args.message);
    this.name = 'MaxioTypedApiError';
    this.statusCode = args.statusCode;
    this.errorType = args.errorType;
    this.errors = args.errors;
  }
}

export interface StartCheckoutInput {
  firstName: string;
  lastName: string;
  email: string;
  organization?: string;
  planName?: string;
  priceCents?: number;
}

export interface StartCheckoutResult {
  sessionId: string;
  demo: boolean;
  approveUrl: string;
  summary: {
    customerId?: number;
    productId?: number;
    subscriptionId?: number;
    invoiceUid?: string;
    invoiceNumber?: string;
    amount: string;
    planName: string;
    paypalOrderId?: string;
  };
}

export interface CompleteCheckoutResult {
  demo: boolean;
  paidStatus: string;
  invoiceStatus?: string;
  invoiceDueAmount?: string;
  nextBillingDate?: string | null;
  subscriptionState?: string;
  paypalOrderStatus?: string;
  paypalCaptureId?: string;
  summary: CheckoutSession;
}

interface OpenInvoiceSummary {
  reference: string;
  number?: string;
  amount: string;
  format: 'relationship' | 'legacy';
}

function appBaseUrl(): string {
  return (process.env.APP_BASE_URL ?? 'http://localhost:3000').replace(
    /\/$/,
    ''
  );
}

function moneyFromCents(cents: number | bigint): string {
  return (Number(cents) / 100).toFixed(2);
}

function formatApiError(err: unknown): string {
  if (err instanceof MaxioTypedApiError) return err.message;
  if (err instanceof ApiError || err instanceof PayPalApiError) {
    return `HTTP ${err.statusCode}: ${JSON.stringify(err.body)}`;
  }
  if (err instanceof Error) return err.message;
  return String(err);
}

function formatCustomerErrors(
  errors: CustomerErrorResponseErrors | undefined
): string {
  if (!errors) return 'Customer validation failed';
  if (CustomerErrorResponseErrors.isStringArray(errors)) {
    return errors.join('; ');
  }
  if (CustomerErrorResponseErrors.isCustomerError(errors)) {
    return errors.customer ?? JSON.stringify(errors);
  }
  return JSON.stringify(errors);
}

/**
 * Deliberate typed catch for Maxio createCustomer 422.
 * `CustomersApi.createCustomer` throws `CustomerErrorResponseError` on that path.
 */
async function createCustomerOrThrowTyped(
  apis: ReturnType<typeof maxioApis>,
  body: CreateCustomerRequest
): Promise<number> {
  try {
    const customerRes = await apis.customers.createCustomer(body);
    const customerId = customerRes.result.customer?.id;
    if (!customerId) throw new Error('Maxio did not return a customer id');
    return customerId;
  } catch (err) {
    if (err instanceof CustomerErrorResponseError) {
      // Real API failure (HTTP 422), caught by generated error type.
      throw new MaxioTypedApiError({
        message: `Maxio rejected the customer: ${formatCustomerErrors(
          err.result?.errors
        )}`,
        statusCode: err.statusCode,
        errorType: 'CustomerErrorResponseError',
        errors: err.result?.errors ?? err.body,
      });
    }
    throw err;
  }
}

/**
 * Triggers a real Maxio 422 so the typed CustomerErrorResponseError path can be demoed.
 */
export async function provokeCustomerValidationError(): Promise<never> {
  if (!isMaxioConfigured()) {
    throw new Error('Maxio credentials required to provoke a live 422');
  }
  const client = createMaxioClient();
  const apis = maxioApis(client);
  // Empty first/last name is a known Maxio validation failure → 422 + CustomerErrorResponseError
  await createCustomerOrThrowTyped(apis, {
    customer: {
      firstName: '',
      lastName: '',
      email: 'not-a-valid-email',
    },
  });
  throw new Error('Expected Maxio to reject the invalid customer');
}

